309	    /// `write_msg` writes the message there, and `send` commits the slot so the consumer can read
310	    /// it. `send` is the general send: [`send_spin`](MpscProducer::send_spin) and
311	    /// [`send_spin_sleep`](MpscProducer::send_spin_sleep) are `send` with a policy already written.
312	    ///
313	    /// Another producer may claim a free slot first. `send` then calls the policy's
314	    /// [`on_lost`](SendPolicy::on_lost) and goes for the next slot at once, so a lost slot is never
315	    /// an error, and `Err(Full)` means the ring was full when `send` last looked and the policy
316	    /// gave up.
317	    ///
318	    /// While `write_msg` runs, the slot is claimed but not committed, and the consumer, which reads
319	    /// slots in order, cannot read past it. A slow `write_msg` delays every message behind it, and
320	    /// a `write_msg` that panics leaves the slot claimed for good, so the consumer waits at it
321	    /// until the ring is restarted. A consumer asleep on an empty ring is woken after the commit.
322	    ///
323	    /// # Parameters
324	    ///
325	    /// - `self`: this producer, by shared reference, so one handle may be used from several threads
326	    ///   at once.
327	    /// - `policy`: the [`SendPolicy`] `send` asks when the ring is full and tells when it loses a
328	    ///   slot. A closure `|attempt| ...` returning whether to look again is a policy, so `|_|
329	    ///   false` makes one attempt and [`policy::spin`](crate::policy::spin) never gives up.
330	    /// - `write_msg`: the closure that writes the message. `send` calls `write_msg` once, after the
331	    ///   slot is claimed, with a mutable reference to the slot's body, which still holds the bytes
332	    ///   of the message the slot carried last. `write_msg` must write every field, since the
333	    ///   consumer reads any field `write_msg` leaves as those stale bytes. `send` does not call
334	    ///   `write_msg` when it returns `Err(Full)`.
335	    ///
336	    /// # Type parameters
337	    ///
338	    /// - `T`: the message type the slot holds. The size of `T` must be at most the slot size less
339	    ///   [`SLOT_HEADER_BYTES`](super::SLOT_HEADER_BYTES), and its alignment at most
340	    ///   `SLOT_HEADER_BYTES`, or the send panics. For zero-copy, `T` is a [`Desc`](crate::Desc),
341	    ///   the handle of a pool buffer the producer wrote the message into before the send, so
342	    ///   `write_msg` is one small store and the message itself is never copied.
343	    ///
344	    /// # Returns
345	    ///
346	    /// - `Ok(())`: the message is committed, and the consumer can read it.
347	    /// - `Err(Full)`: the policy gave up on a full ring. No slot was claimed, and `write_msg` was
348	    ///   not called.
349	    #[inline(always)]
350	    pub fn send<T>(
351	        &self,
352	        mut policy: impl SendPolicy,
353	        write_msg: impl FnOnce(&mut T),
354	    ) -> Result<(), Full>
355	    where
356	        T: FromBytes + IntoBytes + KnownLayout,
357	    {
358	        let segs = &self.segs;
359	        check_body_type::<T>(segs.slot_size);
360	        let claim = segs.claim();
361	        // SeqCst on every claim word access, as v1's index: the claim is only exclusive if these
362	        // are linearizable.
363	        let mut w = claim.load(Ordering::SeqCst);
364	        let mut attempt = 0u32;
365	        let mut lost = 0u32;
366	        let (seg, pos) = loop {
367	            // Single: segment 0 always, whatever the word's segment bits hold, so the check below
368	            // folds away.
369	            let seg = if M::MULTI { word_seg(w) } else { 0 };
370	            let pos = word_pos(w);
371	            if M::MULTI && seg >= segs.seg_count {
372	                // A scribbled claim word: the ring is wedged, and this degrades toward Full, never
373	                // toward a slot the ring does not have.
374	                return Err(Full);
375	            }
376	            // Acquire pairs with the consumer's Release in release(): a claimable seq means the
377	            // previous lap's reads are done.
378	            let seq = segs.seq(seg, pos).load(Ordering::Acquire);
379	            if seq == pos {
380	                // Claimable. Weak CAS: a spurious failure just retries with the fresher word. The
381	                // consumer's waiting flag carries over, cleared only by the consumer.
382	                match claim.compare_exchange_weak(
383	                    w,
384	                    word(seg, pos.wrapping_add(1)) | (w & WAITING),
385	                    Ordering::SeqCst,
386	                    Ordering::SeqCst,
387	                ) {
388	                    Ok(_) => break (seg, pos),
389	                    Err(actual) => {
390	                        w = actual;
391	                        lost = lost.saturating_add(1);
392	                        policy.on_lost(lost);
393	                    }
394	                }
395	                continue;
396	            }
397	            // Not claimable at pos: a stale word or a full segment, told apart by re-reading, as v1
398	            // does.
399	            let cur = claim.load(Ordering::SeqCst);
400	            if cur != w {
401	                w = cur;
402	                continue;
403	            }
404	            // Single has no segment to switch to: the ring is Full.
405	            let switched = if M::MULTI {
406	                self.switch(w)
407	            } else {
408	                Err(NoSwitch::NoFree)
409	            };
410	            match switched {
411	                Ok(()) | Err(NoSwitch::Lost) => {}
412	                Err(NoSwitch::NoFree) => {
413	                    if !policy.on_full(attempt, &Room { sleeper: self }) {
414	                        return Err(Full);
415	                    }
416	                    attempt = attempt.saturating_add(1);
417	                }
418	            }
419	            w = claim.load(Ordering::SeqCst);
420	        };
421	        // (seg, pos) is exclusively ours until the seq commit store.
422	        let msg = segs.body(seg, pos) as *mut T;
423	        let commit = seq_of(pos.wrapping_add(segs.commit_add));
424	        let seq = segs.seq(seg, pos);
425	        // SAFETY: msg is in-bounds and aligned (check_body_type against the body's offset in a
426	        // line-aligned slot), any byte pattern is a valid T (FromBytes bound), and the claim CAS
427	        // gives exclusive slot access until the commit store below.
428	        write_msg(unsafe { &mut *msg });
429	        // Release pairs with the consumer's Acquire seq load: observing pos + M + 1 means the
430	        // filled bytes are visible.
431	        seq.store(commit, Ordering::Release);
432	        // The claim CAS returned the word it replaced, flag and all, so learning the consumer
433	        // sleeps costs nothing.
434	        if W::WAKES && w & WAITING != 0 {
